        sse_encode_i_32(0, serializer);
        sse_encode_String(delta, serializer);
      case AiChatEvent_Thinking():
        sse_encode_i_32(1, serializer);
      case AiChatEvent_AssistantMessage(text: final text):
        sse_encode_i_32(2, serializer);
        sse_encode_String(text, serializer);
      case AiChatEvent_ToolStarted(name: final name, summary: final summary):
        sse_encode_i_32(3, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(summary, serializer);
      case AiChatEvent_ToolFinished(
        name: final name,
        ok: final ok,
        summary: final summary,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(name, serializer);
        sse_encode_bool(ok, serializer);
        sse_encode_String(summary, serializer);
      case AiChatEvent_DraftReady(draft: final draft):
        sse_encode_i_32(5, serializer);
        sse_encode_box_autoadd_ai_action_draft(draft, serializer);
      case AiChatEvent_TurnDone():
        sse_encode_i_32(6, serializer);
      case AiChatEvent_Failed(detail: final detail):
        sse_encode_i_32(7, serializer);
        sse_encode_String(detail, serializer);
    }
  }

