  @protected
  void sse_encode_command_run_event(
    CommandRunEvent self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CommandRunEvent_Started(
        runId: final runId,
        label: final label,
        command: final command,
        cancellable: final cancellable,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_String(label, serializer);
        sse_encode_String(command, serializer);
        sse_encode_bool(cancellable, serializer);
      case CommandRunEvent_Output(
        runId: final runId,
        stream: final stream,
        lines: final lines,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_command_output_stream(stream, serializer);
        sse_encode_list_String(lines, serializer);
      case CommandRunEvent_Detached(
        runId: final runId,
        elapsedMs: final elapsedMs,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_u_32(elapsedMs, serializer);
      case CommandRunEvent_Finished(
        runId: final runId,
        exitCode: final exitCode,
        elapsedMs: final elapsedMs,
        ok: final ok,
        afterDetach: final afterDetach,
        droppedLines: final droppedLines,
        outputTail: final outputTail,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_opt_box_autoadd_i_32(exitCode, serializer);
        sse_encode_u_32(elapsedMs, serializer);
        sse_encode_bool(ok, serializer);
        sse_encode_bool(afterDetach, serializer);
        sse_encode_u_32(droppedLines, serializer);
        sse_encode_String(outputTail, serializer);
      case CommandRunEvent_Cancelled(
        runId: final runId,
        elapsedMs: final elapsedMs,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_u_32(elapsedMs, serializer);
      case CommandRunEvent_Failed(runId: final runId, detail: final detail):
        sse_encode_i_32(5, serializer);
        sse_encode_String(runId, serializer);
        sse_encode_String(detail, serializer);
    }
  }

