  @protected
  void sse_encode_note_op(NoteOp self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case NoteOp_Save(
        path: final path,
        text: final text,
        baseHash: final baseHash,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(text, serializer);
        sse_encode_opt_String(baseHash, serializer);
      case NoteOp_Delete(path: final path, baseHash: final baseHash):
        sse_encode_i_32(1, serializer);
        sse_encode_String(path, serializer);
        sse_encode_opt_String(baseHash, serializer);
    }
  }

  @protected
  void sse_encode_note_op_result(NoteOpResult self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case NoteOpResult_Saved(path: final path, hash: final hash):
        sse_encode_i_32(0, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(hash, serializer);
      case NoteOpResult_Deleted(path: final path):
        sse_encode_i_32(1, serializer);
        sse_encode_String(path, serializer);
      case NoteOpResult_Conflict(
        path: final path,
        diskText: final diskText,
        diskHash: final diskHash,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(diskText, serializer);
        sse_encode_String(diskHash, serializer);
      case NoteOpResult_Failed(path: final path, detail: final detail):
        sse_encode_i_32(3, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(detail, serializer);
    }
  }

