  @protected
  void sse_encode_pairing_event(PairingEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PairingEvent_DeviceRequestedPairing(
        deviceName: final deviceName,
        platform: final platform,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(deviceName, serializer);
        sse_encode_device_platform(platform, serializer);
      case PairingEvent_HostPinReceived(
        pin: final pin,
        hostName: final hostName,
        hostPlatform: final hostPlatform,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(pin, serializer);
        sse_encode_String(hostName, serializer);
        sse_encode_device_platform(hostPlatform, serializer);
      case PairingEvent_PairingSucceeded(
        deviceId: final deviceId,
        certFingerprint: final certFingerprint,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(deviceId, serializer);
        sse_encode_String(certFingerprint, serializer);
      case PairingEvent_PairingRejected(reason: final reason):
        sse_encode_i_32(3, serializer);
        sse_encode_String(reason, serializer);
      case PairingEvent_PairingRequestedWhileDisarmed(
        deviceName: final deviceName,
        platform: final platform,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(deviceName, serializer);
        sse_encode_device_platform(platform, serializer);
    }
  }

