  @protected
  void sse_encode_usb_event(UsbEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UsbEvent_PhoneDetected(
        vendorId: final vendorId,
        productId: final productId,
        product: final product,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_16(vendorId, serializer);
        sse_encode_u_16(productId, serializer);
        sse_encode_opt_String(product, serializer);
      case UsbEvent_DriverBlocked(
        vendorId: final vendorId,
        productId: final productId,
        driver: final driver,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_u_16(vendorId, serializer);
        sse_encode_u_16(productId, serializer);
        sse_encode_opt_String(driver, serializer);
      case UsbEvent_AccessoryModeStarted():
        sse_encode_i_32(2, serializer);
      case UsbEvent_AccessoryConnected():
        sse_encode_i_32(3, serializer);
      case UsbEvent_AccessoryDisconnected():
        sse_encode_i_32(4, serializer);
      case UsbEvent_Failed(detail: final detail):
        sse_encode_i_32(5, serializer);
        sse_encode_String(detail, serializer);
    }
  }
